<script lang="ts">
/**
 * Auto-generated form component from SMRT object schema
 * Demonstrates "Define Once, Consume Everywhere" - form is generated from Product class definition
 */

import { useI18n } from '@happyvertical/smrt-ui/i18n';
import { Button } from '@happyvertical/smrt-ui/ui';
import { M } from '../../i18n.js';
import type { ProductData } from '../../types';
import FieldRenderer from './FieldRenderer.svelte';

const { t } = useI18n();

interface Props {
  data?: ProductData;
  title?: string;
  submitLabel?: string;
  readonly?: boolean;
  onSubmit?: (data: ProductData) => void;
  onChange?: (data: ProductData) => void;
}

const {
  data = {},
  title = 'Product Information',
  submitLabel = 'Save',
  readonly = false,
  onSubmit,
  onChange,
}: Props = $props();

// Auto-generated field schema from Product class
// In a full implementation, this would be generated by the SMRT plugin
const fieldSchema = [
  {
    name: 'name',
    type: 'string',
    label: 'Product Name',
    required: true,
    placeholder: 'Enter product name',
  },
  {
    name: 'description',
    type: 'string',
    label: 'Description',
    placeholder: 'Product description',
  },
  {
    name: 'category',
    type: 'string',
    label: 'Category',
    placeholder: 'Product category',
  },
  {
    name: 'manufacturer',
    type: 'string',
    label: 'Manufacturer',
    placeholder: 'Manufacturer name',
  },
  {
    name: 'model',
    type: 'string',
    label: 'Model',
    placeholder: 'Product model',
  },
  {
    name: 'specifications',
    type: 'object',
    label: 'Specifications',
    placeholder: 'Technical specifications',
  },
  { name: 'tags', type: 'array', label: 'Tags', placeholder: 'Product tags' },
] as const;

// Reactive form data
let formData = $state({ ...data });

// Update form data when props change
$effect(() => {
  formData = { ...data };
});

function updateField(fieldName: string, value: any) {
  formData[fieldName as keyof ProductData] = value;

  // Trigger change callback
  if (onChange) {
    onChange({ ...formData });
  }
}

function handleSubmit(event: Event) {
  event.preventDefault();
  if (onSubmit && !readonly) {
    onSubmit({ ...formData });
  }
}

function _getFieldType(
  name: string,
): 'string' | 'number' | 'boolean' | 'array' | 'object' {
  const field = fieldSchema.find((f) => f.name === name);
  return field?.type || 'string';
}
</script>

<div class="auto-form">
  <header class="form-header">
    <h2 class="form-title">{title}</h2>
    <div class="form-subtitle">
      {t(M['products.auto_form.subtitle'])}
    </div>
  </header>

  <form class="form-content" onsubmit={handleSubmit}>
    {#each fieldSchema as field}
      <FieldRenderer
        fieldName={field.name}
        fieldType={field.type}
        value={formData[field.name]}
        label={field.label}
        placeholder={field.placeholder}
        required={field.required || false}
        {readonly}
        onUpdate={(value) => updateField(field.name, value)}
      />
    {/each}

    {#if !readonly}
      <div class="form-actions">
        <Button type="submit" variant="primary">
          {submitLabel}
        </Button>
        <Button type="button" variant="secondary" onclick={() => formData = {}}>
          Reset
        </Button>
      </div>
    {/if}
  </form>

  <!-- Demo: Show current form state -->
  <details class="form-debug">
    <summary>{t(M['products.auto_form.debug_summary'])}</summary>
    <pre>{JSON.stringify(formData, null, 2)}</pre>
  </details>
</div>

